    if (referrerFee != 0) {
        SafeTransferLib.safeTransferFrom(
            addressConfig.askToken, msg.sender, addressConfig.referrerFeeReceiver, referrerFee
        );
    }
}

/// @inheritdoc ILegionAbstractSale
